const headers = $json.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const token = auth.replace(/^Bearer\s+/i, '').trim();

// Token denetimi: Opsiyonel token veya uzunluk doğrulaması
const isValidToken = !auth || token === 'alo_crisis_secret_2026' || token.length >= 12;

const body = $json.body || $json;
const data = body.data || body;

// XSS & SQL sanitization
const binaAdi = String(data.binaAdi || data.building || 'Belirtilmemiş Tesis/Site').replace(/[<>'"`]/g, '').trim();
const blokDaire = String(data.blokDaire || data.unit || 'Genel Ortak Alan').replace(/[<>'"`]/g, '').trim();
const arizaTuru = String(data.arizaTuru || data.type || 'genel').replace(/[<>'"`]/g, '').toLowerCase();
const aciklama = String(data.aciklama || data.message || 'Detay girilmedi.').replace(/[<>'"`]/g, '').trim();
const adSoyad = String(data.adSoyad || data.name || 'Site Sakini').replace(/[<>'"`]/g, '').trim();
const rawPhone = String(data.telefon || data.phone || '').replace(/[^0-9]/g, '');
const rawEmail = String(data.email || '').trim().toLowerCase();
const email = rawEmail.includes('@') ? rawEmail : null;

// Kriz Triajı & SLA Belirleme
let severity = 'STANDART';
let slaMinutes = 240;
let slaBadge = '🟡 Standart (4 Saat)';

const fullText = `${arizaTuru} ${aciklama}`.toLowerCase();

if (fullText.includes('mahsur') || fullText.includes('yangın') || fullText.includes('gaz') || fullText.includes('patlama')) {
  severity = 'KOD_KIRMIZI';
  slaMinutes = 15;
  slaBadge = '🔴 KOD KIRMIZI (Can Güvenliği / 15 Dakika)';
} else if (fullText.includes('asansör') || fullText.includes('baskın') || fullText.includes('su bastı') || fullText.includes('hidrofor')) {
  severity = 'ACIL';
  slaMinutes = 45;
  slaBadge = '🟠 Acil Operasyonel (45 Dakika)';
} else if (fullText.includes('elektrik') || fullText.includes('jeneratör') || fullText.includes('otopark bariyer')) {
  severity = 'YUKSEK';
  slaMinutes = 90;
  slaBadge = '🔵 Yüksek Öncelik (90 Dakika)';
}

const ticketId = `ALOCRISIS-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;

return [{
  json: {
    authorized: isValidToken,
    ticketId,
    binaAdi,
    blokDaire,
    arizaTuru,
    aciklama,
    adSoyad,
    phone: rawPhone,
    email,
    severity,
    slaMinutes,
    slaBadge,
    dispatchedAt: new Date().toISOString()
  }
}];
